import { queryOptions, useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import type { UseQueryOptions, UseMutationOptions } from '@tanstack/react-query';
import { useApiService } from './useApiService';
import type { ApiService } from '../client/ApiService';
import { ApiError } from '../errors/ApiError';
import type { Document, DocumentSummary } from '../models';

const documentsKeys = {
  all: ['documents'] as const,
  list: () => [...documentsKeys.all, 'list'] as const,
  getDocumentSummary: (documentId: string, query?: { printable?: boolean /* default: false */ }) => [...documentsKeys.all, 'getDocumentSummary', documentId, query] as const,
};

export { documentsKeys };

/**
 * The query options of each read: spread into useQuery or useSuspenseQuery, or pass to
 * queryClient.prefetchQuery / ensureQueryData (a route loader, server rendering). The query hands
 * React Query's signal to the client, so a cancelled or unused query stops its request.
 */
const documentsQueries = {
  listDocuments: (api: ApiService) => queryOptions<Document[], ApiError>({
    queryKey: documentsKeys.list(),
    queryFn: async ({ signal }) => {
      const result = await api.documents.listDocuments(signal);
      if (result.status === 'ok') {
        return result.data;
      }
      if ('error' in result && result.error instanceof ApiError) {
        throw result.error;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    retry: false,
  }),
  getDocumentSummary: (api: ApiService, documentId: string, query?: { printable?: boolean /* default: false */ }, headers?: { 'If-None-Match'?: string }) => queryOptions<DocumentSummary | Blob, ApiError>({
    queryKey: documentsKeys.getDocumentSummary(documentId, query),
    queryFn: async ({ signal }) => {
      const result = await api.documents.getDocumentSummary(documentId, query, headers, signal);
      if (result.status === 'ok') {
        return result.data;
      }
      if ('error' in result && result.error instanceof ApiError) {
        throw result.error;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    retry: false,
  }),
};

export { documentsQueries };

/** List the uploaded documents */
export function useListDocuments(options?: Omit<UseQueryOptions<Document[], ApiError>, 'queryKey' | 'queryFn'>) {
  const api = useApiService();
  return useQuery({
    ...documentsQueries.listDocuments(api),
    ...options,
  });
}

/** Upload a document - a PDF, an Excel workbook, a PNG or a JPEG - as the raw request body */
export function useUploadDocument(query: { fileName: string }, options?: Omit<UseMutationOptions<Document, ApiError, Blob | File>, 'mutationFn'>) {
  const api = useApiService();
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (file: Blob | File) => {
      const result = await api.documents.uploadDocument(file, query);
      if (result.status === 'created') {
        return result.data;
      }
      if ('error' in result && result.error instanceof ApiError) {
        throw result.error;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
    onSuccess: async (data, variables, onMutateResult, context) => {
      await queryClient.invalidateQueries({ queryKey: documentsKeys.all });
      await options?.onSuccess?.(data, variables, onMutateResult, context);
    },
  });
}

/** Download a document - with its own media type and file name */
export function useGetDocument(options?: Omit<UseMutationOptions<Blob, ApiError, string>, 'mutationFn'>) {
  const api = useApiService();
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (documentId: string) => {
      const result = await api.documents.getDocument(documentId);
      if (result.status === 'ok') {
        return result.data;
      }
      if ('error' in result && result.error instanceof ApiError) {
        throw result.error;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
    onSuccess: async (data, variables, onMutateResult, context) => {
      await queryClient.invalidateQueries({ queryKey: documentsKeys.all });
      await options?.onSuccess?.(data, variables, onMutateResult, context);
    },
  });
}

/** A document's summary - as JSON, or as a printable PDF */
export function useGetDocumentSummary(documentId: string, query?: { printable?: boolean /* default: false */ }, headers?: { 'If-None-Match'?: string }, options?: Omit<UseQueryOptions<DocumentSummary | Blob, ApiError>, 'queryKey' | 'queryFn'>) {
  const api = useApiService();
  return useQuery({
    ...documentsQueries.getDocumentSummary(api, documentId, query, headers),
    ...options,
    enabled: documentId != null && (options?.enabled ?? true),
  });
}

/** Copy a document - answered with 303 See Other to the copy's summary */
export function useCopyDocument(options?: Omit<UseMutationOptions<void, ApiError, string>, 'mutationFn'>) {
  const api = useApiService();
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (documentId: string) => {
      const result = await api.documents.copyDocument(documentId);
      if (result.status === 'ok') {
        return;
      }
      if ('error' in result && result.error instanceof ApiError) {
        throw result.error;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
    onSuccess: async (data, variables, onMutateResult, context) => {
      await queryClient.invalidateQueries({ queryKey: documentsKeys.all });
      await options?.onSuccess?.(data, variables, onMutateResult, context);
    },
  });
}